<script setup>
import { ref, onMounted, computed } from 'vue';
import { api, send, session } from './api';
import { permissions } from './permissions';
const access=computed(()=>permissions(session.user)),rows=ref([]),q=ref(''),error=ref(''),message=ref(''),busy=ref(false),exhausted=ref(false),supervisorEmails=ref({});
async function search(more=false){busy.value=true;error.value='';try{const cursor=more?rows.value.at(-1)?.id||'':'';const batch=await api('/team/coaches?q='+encodeURIComponent(q.value)+'&after='+encodeURIComponent(cursor));rows.value=more?[...rows.value,...batch]:batch;exhausted.value=batch.length<30;}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function assign(coach,clear=false){busy.value=true;error.value='';message.value='';try{let supervisorId=null;if(!clear){const email=(supervisorEmails.value[coach.id]||'').trim();if(!email)throw new Error('Enter the supervisor’s registered email.');const members=await api('/admin/members?role=Supervisor&q='+encodeURIComponent(email));const supervisor=members.find(x=>x.email.toLowerCase()===email.toLowerCase());if(!supervisor)throw new Error('No approved supervisor matches that email. Grant supervisor access in Member access first.');supervisorId=supervisor.id;}await send('/admin/supervision/'+encodeURIComponent(coach.id),{supervisorId},'PUT');message.value=clear?'Supervisor assignment removed.':'Supervisor assigned.';await search();}catch(e){error.value=e.message;}finally{busy.value=false;}}
onMounted(()=>{if(access.value.team)search();});
</script>
<template><section v-if="!access.team" class="card"><h1>Team access required.</h1></section><template v-else><div class="page-heading"><div><p class="eyebrow">PEOPLE, PLANS AND PROGRESS</p><h1>Your coaching team<span class="lime-dot">.</span></h1><p>{{access.admin?'Assign approved coaches to the right supervisor.':'A focused view of the coaches assigned to you.'}}</p></div><span class="tag">{{access.label}}</span></div><section class="card"><form class="search-row" @submit.prevent="search()"><label>Find coach by email<input v-model="q" type="search" maxlength="100" placeholder="coach@example.com"></label><button :disabled="busy">Search</button></form><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="message" class="notice" role="status">{{message}}</p><div class="table-scroll"><table><thead><tr><th>Coach</th><th>Email</th><th>Active students</th><th>Supervisor</th><th v-if="access.admin">Assignment</th></tr></thead><tbody><tr v-for="c in rows" :key="c.id"><td>{{c.displayName||'Coach'}}</td><td>{{c.email}}</td><td>{{c.activeStudents}}</td><td>{{c.supervisorName||'Not assigned'}}</td><td v-if="access.admin"><div class="team-controls"><label :for="'supervisor-'+c.id">Supervisor email<input :id="'supervisor-'+c.id" v-model="supervisorEmails[c.id]" type="email" placeholder="supervisor@example.com" :disabled="busy"></label><button class="secondary" :disabled="busy" @click="assign(c)">Assign</button><button v-if="c.supervisorId" class="text-button" :disabled="busy" @click="assign(c,true)">Remove assignment</button></div></td></tr></tbody></table></div><p v-if="!busy&&!rows.length" class="muted">{{access.admin?'No approved coaches match this search.':'No coaches assigned to you yet. Ask your administrator to set up your team.'}}</p><button v-if="!exhausted" class="text-button" :disabled="busy" @click="search(true)">Load more coaches</button><p class="hint">Supervisory access covers team membership and active student counts. It does not grant access to athletes’ measurements, meal diaries or plans. Those remain subject to the athlete’s individual coaching consent.</p></section></template></template>
